const keys=new Set();let joy={x:0,y:0},jumpTime=0,roarCooldown=0,score=0,found=0,playing=true,won=false,soundOn=false,audioCtx=null,lastToast=0;
const toastEl=document.querySelector('#toast');function toast(text){toastEl.textContent=text;toastEl.classList.add('show');clearTimeout(lastToast);lastToast=setTimeout(()=>toastEl.classList.remove('show'),1900)}
function chirp(freq=520,dur=.12,type='sine'){if(!soundOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.08,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch(e){}}
function setCount(){document.querySelector('#count').textContent=`${found} / 5`;document.querySelector('#progress').style.width=`${found*20}%`;document.querySelector('#score').textContent=String(score).padStart(3,'0');}
function showHelp(){playing=false;document.querySelector('#modalEmoji').textContent='🐾';document.querySelector('#modalTitle').textContent='A tiny guide to chaos';document.querySelector('#modalText').innerHTML='Wander the moonlit streets and touch all <b>5 glowing shards</b>. Use your monster roar to scare the patrol bots, then reach the shimmering gate at the far end of town.<br><br><b>Move:</b> WASD / arrows or the thumbstick · <b>Roar:</b> Space / ROAR · <b>Hop:</b> Shift / HOP';document.querySelector('#modalButton').textContent='BACK TO THE MISSION';document.querySelector('#modal').classList.add('show');}
document.querySelector('#help').addEventListener('click',showHelp);
document.querySelector('#modalButton').addEventListener('click',()=>{document.querySelector('#modal').classList.remove('show');if(won){resetGame()}playing=true;});
document.querySelector('#sound').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♩';if(soundOn)chirp(660,.1)});
const movementKeys=['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','ShiftLeft','ShiftRight'];window.addEventListener('keydown',e=>{if(movementKeys.includes(e.code))e.preventDefault();keys.add(e.code);if(!e.repeat&&e.code==='Space')roar();if(!e.repeat&&(e.code==='ShiftLeft'||e.code==='ShiftRight'))hop();});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
const stick=document.querySelector('#stick'),nub=document.querySelector('#nub');let pointer=null;function setJoy(e){const r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=38,d=Math.hypot(dx,dy),scale=d>max?max/d:1;joy={x:dx*scale/max,y:-dy*scale/max};nub.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;}
stick.addEventListener('pointerdown',e=>{e.preventDefault();pointer=e.pointerId;stick.setPointerCapture(pointer);setJoy(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===pointer)setJoy(e)});function releaseJoy(e){if(pointer===e.pointerId){pointer=null;joy={x:0,y:0};nub.style.transform='translate(0,0)'}}stick.addEventListener('pointerup',releaseJoy);stick.addEventListener('pointercancel',releaseJoy);
document.querySelector('#roarBtn').addEventListener('pointerdown',e=>{e.preventDefault();roar()});document.querySelector('#jumpBtn').addEventListener('pointerdown',e=>{e.preventDefault();hop()});
function hop(){if(!playing||jumpTime>0)return;jumpTime=.62;chirp(380,.09,'triangle')}
const catPos=cat.position;const forward=new THREE.Vector3();
function roar(){if(!playing||roarCooldown>0)return;roarCooldown=1.6;chirp(110,.28,'sawtooth');setTimeout(()=>chirp(72,.22,'triangle'),55);cat.scale.set(1.16,.9,1.16);setTimeout(()=>cat.scale.setScalar(1.02),150);let hit=0;enemies.forEach(e=>{if(!e.stun&&e.group.position.distanceTo(catPos)<7){e.stun=4;e.group.rotation.z=Math.PI/2;hit++}});if(hit){score+=hit*10;setCount();toast(`MONSTER ROAR! ${hit} patrol ${hit===1?'scared':'scared'} ✨`)}else toast('MRAOW! The whole town heard that!');}
function collectShard(s){s.taken=true;scene.remove(s.group);found++;score+=20;setCount();chirp(700,.13);setTimeout(()=>chirp(950,.18),85);if(found===5){document.querySelector('#missionTitle').textContent='All shards found!';document.querySelector('#objective').innerHTML='THE GATE IS OPEN <span>✦</span>';gateLight.intensity=30;portal.material.emissive.set('#60ffc9');toast('The gate is awake! Find the glowing arch ✨')}else toast(`Moon shard found! ${found} of 5 ✦`)}
function win(){if(won)return;won=true;playing=false;chirp(880,.3);setTimeout(()=>chirp(1100,.4),180);document.querySelector('#modalEmoji').textContent='🌟';document.querySelector('#modalTitle').textContent='Town saved. Probably.';document.querySelector('#modalText').innerHTML=`You found every moon shard and made it through the gate. The sleepy town will never be quite the same.<br><br><b>Chaos score: ${score}</b> · Nice monster work!`;document.querySelector('#modalButton').textContent='PLAY AGAIN';document.querySelector('#modal').classList.add('show');}
function resetGame(){found=0;score=0;won=false;shards.forEach(s=>{s.taken=false;scene.add(s.group)});enemies.forEach((e,i)=>{e.stun=0;e.group.rotation.z=0;e.group.position.set(e.baseX,0,e.baseZ)});catPos.set(0,0,16);gateLight.intensity=0;portal.material.emissive.set('#5388ff');document.querySelector('#missionTitle').textContent='Find the moon shards';document.querySelector('#objective').innerHTML='COLLECT THE SHARDS <span>✦</span>';setCount();toast('Fresh night, fresh chaos. Go!');}
const clock=new THREE.Clock();camera.position.set(0,8,27);camera.lookAt(0,1,16);setCount();toast('Find the glowing shards — your roar scares the guards!');
function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.04),t=clock.elapsedTime;
if(playing){let ix=joy.x,iz=-joy.y;if(keys.has('KeyA')||keys.has('ArrowLeft'))ix-=1;if(keys.has('KeyD')||keys.has('ArrowRight'))ix+=1;if(keys.has('KeyW')||keys.has('ArrowUp'))iz-=1;if(keys.has('KeyS')||keys.has('ArrowDown'))iz+=1;const len=Math.hypot(ix,iz);if(len>1){ix/=len;iz/=len}const speed=7.1;if(len>.08){catPos.x+=ix*speed*dt;catPos.z+=iz*speed*dt;cat.rotation.y=Math.atan2(ix,-iz);body.rotation.x=Math.sin(t*13)*.045;body.position.y=Math.abs(Math.sin(t*13))*.1}else body.rotation.x=0;catPos.x=THREE.MathUtils.clamp(catPos.x,-8.7,8.7);catPos.z=THREE.MathUtils.clamp(catPos.z,-42,25);
if(jumpTime>0){jumpTime-=dt;body.position.y=Math.sin((.62-jumpTime)/.62*Math.PI)*1.05}else body.position.y=0;tail.rotation.x=Math.sin(t*4)*.28;tail.rotation.z=Math.sin(t*3)*.22;
shards.forEach(s=>{if(s.taken)return;s.group.position.y=s.baseY+Math.sin(t*2.2+s.phase)*.18;s.group.rotation.y=t*.7+s.phase;if(catPos.distanceTo(s.group.position)<1.25)collectShard(s)});
enemies.forEach(e=>{if(e.stun>0){e.stun-=dt;e.group.position.y=.35+Math.sin(t*12)*.08;if(e.stun<=0){e.group.rotation.z=0;e.group.position.y=0}}else{e.group.position.y=Math.abs(Math.sin(t*4+e.phase))*.07;e.group.position.x=e.baseX+Math.sin(t*.8+e.phase)*.6;e.group.rotation.y=Math.cos(t*.8+e.phase)*.35}});
if(found===5&&catPos.z<-35&&Math.abs(catPos.x)<3.1)win();}
// Soft trailing follow camera; keep the player in the lower third.
const desired=new THREE.Vector3(catPos.x*.72,catPos.y+7.5,catPos.z+10.5);camera.position.lerp(desired,1-Math.exp(-dt*3));const look=new THREE.Vector3(catPos.x*.55,1.05,catPos.z-3.5);camera.lookAt(look);renderer.render(scene,camera);}
requestAnimationFrame(frame);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight)});
</script>
</body></html>

