 const houseMats=[cream,pink,purple,mint];for(let side of [-1,1])for(let i=0;i<7;i++){const z=-38+i*13+Math.random()*3,x=side*(12+Math.random()*2),w=6+Math.random()*2,d=7+Math.random()*2,h=5+Math.random()*2,g=new THREE.Group();g.position.set(x,0,z);scene.add(g);box(g,0,h/2,0,w,h,d,houseMats[(i+(side>0?2:0))%4]);const roof=new THREE.Mesh(new THREE.ConeGeometry(w*.78,3.2,4),roofMat);roof.position.set(0,h+1.35,0);roof.rotation.y=Math.PI/4;roof.castShadow=true;g.add(roof);box(g,0,1.2,d/2+.055,1.35,2.4,.15,dark);for(let wx of [-1.8,1.8])box(g,wx,3,d/2+.08,1.05,1.25,.12,mat('#f9d890',.4,'#e8a34b',.7));box(g,0,h-.3,d/2+.2,2,.22,.35,mat('#f7d49e'))}
